import math
import os
import sys
from io import BytesIO, IOBase
from collections import defaultdict
from bisect import bisect_left

def main():
	for _ in range(int(input())):
		n = int(input())
		arr = list(map(int, input().split()))
		dct = defaultdict(list)
		for (i, item) in enumerate(arr):
			dct[item].append(i)
		col = n.bit_length()
		sparse = [[-1 for _ in range(col)] for _ in range(n)]
		for c in range(col):
			for r in range(n):
				if c == 0:
					sparse[r][c] = r
					continue
				if r + (1 << c) <= n:
					z = 1 << c
					if arr[sparse[r][c - 1]] < arr[sparse[r + (z >> 1)][c - 1]]:
						sparse[r][c] = sparse[r][c - 1]
					else:
						sparse[r][c] = sparse[r + (z >> 1)][c - 1]
				else:
					break
		postmax = [0] * (n + 1)
		dctz = dict()
		for i in range(n):
			postmax[n - i - 1] = max(postmax[n - i], arr[n - i - 1])
		postmax.pop()
		for i in range(n - 2, -1, -1):
			if postmax[i] != postmax[i + 1]:
				dctz[postmax[i + 1]] = i
		dctz[postmax[0]] = -1

		def findmin(l, r):
			z = r - l + 1
			k = z.bit_length() - 1
			ans = arr[sparse[l][k]]
			z -= 1 << k
			if z:
				ans = min(ans, arr[sparse[l + z][k]])
			return ans
		pre = 0
		ans = 0
		for i in range(n):
			pre = max(pre, arr[i])
			if pre in dctz:
				y = dct[pre]
				x = bisect_left(y, i + 1)
				if x != len(y):
					z = max(y[x], dctz[pre])
					if z != n - 1 and findmin(i + 1, z) == pre and (postmax[z + 1] == pre):
						ans = [i + 1, z - i, n - z - 1]
						break
		if ans:
			print('YES')
			print(*ans)
		else:
			print('NO')
BUFSIZE = 8192

class FastIO(IOBase):
	newlines = 0

	def __init__(self, file):
		self._fd = file.fileno()
		self.buffer = BytesIO()
		self.writable = 'x' in file.mode or 'r' not in file.mode
		self.write = self.buffer.write if self.writable else None

	def read(self):
		while True:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			if not b:
				break
			ptr = self.buffer.tell()
			(self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
		self.newlines = 0
		return self.buffer.read()

	def readline(self):
		while self.newlines == 0:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			self.newlines = b.count(b'\n') + (not b)
			ptr = self.buffer.tell()
			(self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
		self.newlines -= 1
		return self.buffer.readline()

	def flush(self):
		if self.writable:
			os.write(self._fd, self.buffer.getvalue())
			(self.buffer.truncate(0), self.buffer.seek(0))

class IOWrapper(IOBase):

	def __init__(self, file):
		self.buffer = FastIO(file)
		self.flush = self.buffer.flush
		self.writable = self.buffer.writable
		self.write = lambda s: self.buffer.write(s.encode('ascii'))
		self.read = lambda : self.buffer.read().decode('ascii')
		self.readline = lambda : self.buffer.readline().decode('ascii')
(sys.stdin, sys.stdout) = (IOWrapper(sys.stdin), IOWrapper(sys.stdout))
input = lambda : sys.stdin.readline().rstrip('\r\n')
main()
